function onVehiclePhotoSelect(e){
  const t=e.target.files&&e.target.files[0];
  if(!t)return;
  const n=new FileReader;
  n.onload=()=>{
    const img=new Image;
    img.onload=()=>{
      let w=img.naturalWidth||360,h=img.naturalHeight||220;
      if(w>360){h=Math.round(360*h/w);w=360}
      const c=document.createElement("canvas");
      c.width=w;c.height=h;
      c.getContext("2d").drawImage(img,0,0,w,h);
      pendingVehiclePhoto=c.toDataURL("image/jpeg",.7);
      const pv=document.getElementById("vh-photo-preview"),cl=document.getElementById("vh-photo-clear");
      if(pv){pv.src=pendingVehiclePhoto;pv.classList.remove("dp-hidden")}
      if(cl)cl.classList.remove("dp-hidden");
      showToast("📷 Araç resmi hazırlandı.");
    };
    img.src=n.result;
  };
  n.readAsDataURL(t);
}
function clearVehiclePhoto(){
  pendingVehiclePhoto="";
  const pv=document.getElementById("vh-photo-preview"),cl=document.getElementById("vh-photo-clear"),fl=document.getElementById("vh-photo-file");
  if(pv){pv.src="";pv.classList.add("dp-hidden")}
  if(cl)cl.classList.add("dp-hidden");
  if(fl)fl.value="";
}
function openVehicleModal(editId=""){
  const v=(envelope.data.vehicles||[]).find(x=>x.id===editId)||null;
  document.getElementById("vh-edit-id").value=v?v.id:"";
  document.getElementById("vh-modal-title").textContent=v?`✏️ ${v.name} — Araç & Ruhsat Düzenle`:"🚗 Yeni Araç Ekle";
  document.getElementById("vh-name").value=v?v.name||"":"";
  document.getElementById("vh-plate").value=v?v.plate||"":"";
  document.getElementById("vh-km").value=v&&v.currentKm!=null?v.currentKm:"";
  const fuels=v&&Array.isArray(v.fuels)?v.fuels:["Benzin"];
  document.querySelectorAll('input[name="vh-fuel"]').forEach(cb=>{cb.checked=fuels.includes(cb.value)});
  const r=(v&&v.ruhsat)||{};
  document.getElementById("vh-ruh-owner").value=r.owner||"";
  document.getElementById("vh-ruh-seri").value=r.seriNo||"";
  document.getElementById("vh-ruh-year").value=r.modelYear||"";
  document.getElementById("vh-ruh-class").value=r.vehicleClass||"";
  document.getElementById("vh-ruh-tescil").value=r.tescilDate||"";
  document.getElementById("vh-ruh-chassis").value=r.chassisNo||"";
  document.getElementById("vh-ruh-engine").value=r.engineNo||"";
  const oil=(v&&v.oil)||{};
  document.getElementById("vh-oil-lastkm").value=oil.lastKm!=null&&oil.lastKm!==""?oil.lastKm:"";
  document.getElementById("vh-oil-intkm").value=oil.intervalKm||10000;
  document.getElementById("vh-oil-lastdate").value=oil.lastDate||"";
  document.getElementById("vh-oil-nextdate").value=oil.nextDate||"";
  const mnt=(v&&v.maint)||{};
  document.getElementById("vh-mnt-lastkm").value=mnt.lastKm!=null&&mnt.lastKm!==""?mnt.lastKm:"";
  document.getElementById("vh-mnt-intkm").value=mnt.intervalKm||15000;
  document.getElementById("vh-mnt-lastdate").value=mnt.lastDate||"";
  document.getElementById("vh-mnt-nextdate").value=mnt.nextDate||"";
  document.getElementById("vh-mnt-note").value=mnt.generalNote||"";
  const dt=(v&&v.dates)||{};
  document.getElementById("vh-muayene-end").value=dt.muayeneEnd||"";
  document.getElementById("vh-trafik-end").value=dt.trafikEnd||"";
  document.getElementById("vh-kasko-end").value=dt.kaskoEnd||"";
  pendingVehiclePhoto=v&&v.photo?v.photo:"";
  const pv=document.getElementById("vh-photo-preview"),cl=document.getElementById("vh-photo-clear"),fl=document.getElementById("vh-photo-file");
  if(fl)fl.value="";
  if(pendingVehiclePhoto){
    if(pv){pv.src=pendingVehiclePhoto;pv.classList.remove("dp-hidden")}
    if(cl)cl.classList.remove("dp-hidden");
  }else{
    if(pv){pv.src="";pv.classList.add("dp-hidden")}
    if(cl)cl.classList.add("dp-hidden");
  }
  document.getElementById("modal-vehicle").classList.remove("dp-hidden");
}
function saveVehicleModal(e){
  e.preventDefault();
  const editId=document.getElementById("vh-edit-id").value.trim();
  const name=document.getElementById("vh-name").value.trim();
  const plate=document.getElementById("vh-plate").value.trim().toUpperCase();
  const currentKm=Math.max(0,parseInt(document.getElementById("vh-km").value,10)||0);
  const fuels=[...document.querySelectorAll('input[name="vh-fuel"]:checked')].map(x=>x.value);
  if(!name)return;
  if(fuels.length===0){showToast("⚠️ Lütfen en az bir yakıt tipi seçin.");return;}
  const obj={
    id:editId||("vh_"+Date.now()+"_"+Math.random().toString(36).slice(2,5)),
    name,plate,fuels,
    photo:pendingVehiclePhoto||"",
    currentKm,
    ruhsat:{
      owner:document.getElementById("vh-ruh-owner").value.trim(),
      seriNo:document.getElementById("vh-ruh-seri").value.trim().toUpperCase(),
      modelYear:document.getElementById("vh-ruh-year").value.trim(),
      vehicleClass:document.getElementById("vh-ruh-class").value.trim(),
      tescilDate:document.getElementById("vh-ruh-tescil").value,
      chassisNo:document.getElementById("vh-ruh-chassis").value.trim().toUpperCase(),
      engineNo:document.getElementById("vh-ruh-engine").value.trim().toUpperCase()
    },
    oil:{
      lastKm:Math.max(0,parseInt(document.getElementById("vh-oil-lastkm").value,10)||0),
      intervalKm:Math.max(1000,parseInt(document.getElementById("vh-oil-intkm").value,10)||10000),
      lastDate:document.getElementById("vh-oil-lastdate").value,
      nextDate:document.getElementById("vh-oil-nextdate").value
    },
    maint:{
      lastKm:Math.max(0,parseInt(document.getElementById("vh-mnt-lastkm").value,10)||0),
      intervalKm:Math.max(1000,parseInt(document.getElementById("vh-mnt-intkm").value,10)||15000),
      lastDate:document.getElementById("vh-mnt-lastdate").value,
      nextDate:document.getElementById("vh-mnt-nextdate").value,
      generalNote:document.getElementById("vh-mnt-note").value.trim()
    },
    dates:{
      muayeneEnd:document.getElementById("vh-muayene-end").value,
      trafikEnd:document.getElementById("vh-trafik-end").value,
      kaskoEnd:document.getElementById("vh-kasko-end").value
    }
  };
  Array.isArray(envelope.data.vehicles)||(envelope.data.vehicles=[]);
  if(editId){
    const idx=envelope.data.vehicles.findIndex(x=>x.id===editId);
    if(idx>-1)envelope.data.vehicles[idx]=obj;else envelope.data.vehicles.push(obj);
  }else{
    envelope.data.vehicles.push(obj);
  }
  closeModal("modal-vehicle");
  saveState();
  renderAll();
  showToast(editId?`✏️ "${name}" güncellendi.`:`🚗 "${name}" araçlara eklendi.`);
}
function quickUpdateVehicleKm(id){
  const v=(envelope.data.vehicles||[]).find(x=>x.id===id);
  const inp=document.getElementById("vh-quick-km-"+id);
  if(!v||!inp)return;
  const km=Math.max(0,parseInt(inp.value,10)||0);
  v.currentKm=km;
  saveState();
  renderVehicles();
  showToast(`📍 "${v.name}" güncel km: ${km.toLocaleString("tr-TR")} km`);
}
function calcDateDiffDays(dateStr){
  if(!dateStr)return null;
  const today=new Date(toLocalDateStr()+"T00:00:00");
  const target=new Date(dateStr+"T00:00:00");
  if(isNaN(target))return null;
  return Math.round((target-today)/864e5);
}
function formatDateBadgeHtml(label,dateStr){
  if(!dateStr)return `<div style="display:flex;justify-content:space-between;align-items:center;font-size:11.5px;padding:3px 0;color:#64748b"><span>${label}</span><span>Girilmedi</span></div>`;
  const d=calcDateDiffDays(dateStr);
  let cls="dp-b-emerald",txt=`${d} gün`;
  if(d<0){cls="dp-b-rose";txt=`${Math.abs(d)} gün geçti!`}
  else if(d===0){cls="dp-b-rose";txt="Bugün!"}
  else if(d<=30){cls="dp-b-amber";txt=`${d} gün kaldı`}
  const trDate=dateStr.split("-").reverse().join(".");
  return `<div style="display:flex;justify-content:space-between;align-items:center;font-size:11.5px;padding:3px 0;gap:6px"><span style="color:#cbd5e1">${label}</span><span style="display:inline-flex;align-items:center;gap:6px"><span class="dp-num" style="color:#94a3b8">${trDate}</span><span class="dp-badge ${cls} dp-num">${txt}</span></span></div>`;
}
